54	void cif_set_base_addr(uint32_t link, void *mac_base, void *wrap_base)
55	{
56		uintptr_t *addr = cif_get_mac_phys_reg_bases(link);
57		int i = 0;
58	
59		for (i = 0; i < CIF_MAC_BLK_ID_MAX; ++i) {
60			addr[i] -= mac_reg_base[link];
61			addr[i] += (uintptr_t)mac_base;
62		}
63		mac_reg_base[link] = (uintptr_t)mac_base;
64	
65		addr = cif_get_wrap_phys_reg_bases(link);
66	
67		for (i = 0; i < CIF_WRAP_BLK_ID_MAX; ++i) {
68			addr[i] -= wrap_reg_base[link];
69			addr[i] += (uintptr_t)wrap_base;
70		}
71		wrap_reg_base[link] = (uintptr_t)wrap_base;
72	}
