62	int gc2083_read_register(VI_PIPE ViPipe, int addr)
63	{
64		int ret, data;
65		CVI_U8 buf[8];
66		CVI_U8 idx = 0;
67	
68		if (g_fd[ViPipe] < 0)
69			return CVI_FAILURE;
70	
71		if (gc2083_addr_byte == 2)
72			buf[idx++] = (addr >> 8) & 0xff;
73	
74		// add address byte 0
75		buf[idx++] = addr & 0xff;
76	
77		ret = write(g_fd[ViPipe], buf, gc2083_addr_byte);
78		if (ret < 0) {
79			CVI_TRACE_SNS(CVI_DBG_ERR, "I2C_WRITE error!\n");
80			return ret;
81		}
82	
83		buf[0] = 0;
84		buf[1] = 0;
85		ret = read(g_fd[ViPipe], buf, gc2083_data_byte);
86		if (ret < 0) {
87			CVI_TRACE_SNS(CVI_DBG_ERR, "I2C_READ error!\n");
88			return ret;
89		}
90	
91		// pack read back data
92		data = 0;
93		if (gc2083_data_byte == 2) {
94			data = buf[0] << 8;
95			data += buf[1];
96		} else {
97			data = buf[0];
98		}
99	
100		syslog(LOG_DEBUG, "i2c r 0x%x = 0x%x\n", addr, data);
101		return data;
102	}
