721	static void _cif_csi_config(struct cif_ctx *ctx,
722				   struct param_csi *param)
723	{
724		uintptr_t wrap_4l = ctx->wrap_phys_regs[CIF_WRAP_BLK_ID_4L];
725		uintptr_t wrap_2l = ctx->wrap_phys_regs[CIF_WRAP_BLK_ID_2L];
726		uintptr_t mac_top = ctx->mac_phys_regs[CIF_MAC_BLK_ID_TOP];
727		uintptr_t mac_csi = ctx->mac_phys_regs[CIF_MAC_BLK_ID_CSI];
728	
729		/* Config the sensor mode */
730		CIF_WR_BITS(mac_top, REG_SENSOR_MAC_T,
731				     REG_00, SENSOR_MAC_MODE,
732				     1);
733		/* invert the HS/VS */
734		CIF_WR_BITS(mac_top, REG_SENSOR_MAC_T,
735				     REG_00, CSI_VS_INV,
736				     1);
737		CIF_WR_BITS(mac_top, REG_SENSOR_MAC_T,
738				     REG_00, CSI_HS_INV,
739				     1);
740		/* CSI controller enable */
741		CIF_WR_BITS(mac_top, REG_SENSOR_MAC_T,
742				     REG_00, CSI_CTRL_ENABLE,
743				     1);
744		/* Config the lane enable */
745		CIF_WR_BITS(mac_csi, REG_CSI_CTRL_TOP_T,
746				     REG_00, CSI_LANE_MODE,
747				     param->lane_num - 1);
748		/* Config the VS gen mode */
749		CIF_WR_BITS(mac_csi, REG_CSI_CTRL_TOP_T,
750				     REG_70, CSI_VS_GEN_MODE,
751				     param->vs_gen_mode);
752		if (!ctx->mac_num) {
753			/* [Note] disable auto_ignore and auto sync by default. */
754			CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
755					     REG_10, AUTO_IGNORE,
756					     0);
757			CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
758					     REG_10, AUTO_SYNC,
759					     0);
760			/* DPHY sensor mode select */
761			CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
762					     REG_00, SENSOR_MODE,
763					     0);
764		} else {
765			/* [Note] disable auto_ignore and auto sync by default. */
766			CIF_WR_BITS(wrap_2l, REG_SENSOR_PHY_2L_T,
767					     REG_10, AUTO_IGNORE,
768					     0);
769			CIF_WR_BITS(wrap_2l, REG_SENSOR_PHY_2L_T,
770					     REG_10, AUTO_SYNC,
771					     0);
772			/* DPHY sensor mode select */
773			CIF_WR_BITS(wrap_2l, REG_SENSOR_PHY_2L_T,
774					     REG_00, SENSOR_MODE,
775					     0);
776		}
777		/* Config csi vc mapping */
778		CIF_WR_BITS(mac_csi, REG_CSI_CTRL_TOP_T,
779				     REG_18, CSI_VC_MAP_CH00,
780				     param->vc_mapping[0]);
781		CIF_WR_BITS(mac_csi, REG_CSI_CTRL_TOP_T,
782				     REG_18, CSI_VC_MAP_CH01,
783				     param->vc_mapping[1]);
784		CIF_WR_BITS(mac_csi, REG_CSI_CTRL_TOP_T,
785				     REG_18, CSI_VC_MAP_CH10,
786				     param->vc_mapping[2]);
787		CIF_WR_BITS(mac_csi, REG_CSI_CTRL_TOP_T,
788				     REG_18, CSI_VC_MAP_CH11,
789				     param->vc_mapping[3]);
790	}
