468	static int _cif_set_attr_mipi(struct cvi_cif_dev *dev,
469				      struct cif_ctx *ctx,
470				      struct mipi_dev_attr_s *attr)
471	{
472		struct combo_dev_attr_s *combo =
473			container_of(attr, struct combo_dev_attr_s, mipi_attr);
474		struct cif_param *param = ctx->cur_config;
475		struct param_csi *csi = &param->cfg.csi;
476		struct mipi_demux_info_s *info = &attr->demux;
477		uint8_t tbl = 0x1F;
478		int i, j = 0, clk_port = 0;
479		uint32_t value;
480	
481		param->type = CIF_TYPE_CSI;
482		/* config the bit mode. */
483		switch (attr->raw_data_type) {
484		case RAW_DATA_8BIT:
485			csi->fmt = CSI_RAW_8;
486			csi->decode_type = 0x2A;
487			break;
488		case RAW_DATA_10BIT:
489			csi->fmt = CSI_RAW_10;
490			csi->decode_type = 0x2B;
491			break;
492		case RAW_DATA_12BIT:
493			csi->fmt = CSI_RAW_12;
494			csi->decode_type = 0x2C;
495			break;
496		case YUV422_8BIT:
497			csi->fmt = CSI_YUV422_8B;
498			csi->decode_type = 0x1E;
499			break;
500		case YUV422_10BIT:
501			csi->fmt = CSI_YUV422_10B;
502			csi->decode_type = 0x1F;
503			break;
504		default:
505			return -EINVAL;
506		}
507		/* config the lane id */
508		for (i = 0; i < CIF_LANE_NUM; i++) {
509			if (attr->lane_id[i] < 0)
510				continue;
511			if (attr->lane_id[i] >= CIF_PHY_LANE_NUM)
512				return -EINVAL;
513			if (!i)
514				clk_port = LANE_IS_PORT1(attr->lane_id[i]);
515			else {
516				if (LANE_IS_PORT1(attr->lane_id[i]) != clk_port)
517					clk_port = -1;
518			}
519			cif_set_lane_id(ctx, i, attr->lane_id[i], attr->pn_swap[i]);
520			/* clear pad ctrl pu/pd */
521			if (dev->pad_ctrl) {
522				value = ioread32(dev->pad_ctrl + PSD_CTRL_OFFSET(attr->lane_id[i]));
523				value &= ~(PAD_CTRL_PU | PAD_CTRL_PD);
524				iowrite32(value, dev->pad_ctrl + PSD_CTRL_OFFSET(attr->lane_id[i]));
525				value = ioread32(dev->pad_ctrl + PSD_CTRL_OFFSET(attr->lane_id[i]) + 4);
526				value &= ~(PAD_CTRL_PU | PAD_CTRL_PD);
527				iowrite32(value, dev->pad_ctrl + PSD_CTRL_OFFSET(attr->lane_id[i]) + 4);
528			}
529			tbl &= ~(1<<attr->lane_id[i]);
530			j++;
531		}
532		csi->lane_num = j - 1;
533		while (ffs(tbl)) {
534			uint32_t idx = ffs(tbl) - 1;
535	
536			cif_set_lane_id(ctx, j++, idx, 0);
537			tbl &= ~(1 << idx);
538		}
539		/* config  clock buffer direction.
540		 * 1. When clock is between 0~2 and 1c4d, direction is P0->P1.
541		 * 2. When clock is between 3~5 and 1c4d, direction is P1->P0.
542		 * 3. When clock and data is between 0~2 and 1c2d, direction bit is freerun.
543		 * 4. When clock is between 0~2 but data is not, direction is P0->P1.
544		 * 5. When clock and data is between 3~5 and 1c2d and mac1 is used, direction bit is freerun.
545		 * 6. When clock is between 3~5 but data is not, direction is P1->P0.
546		 */
547		if (csi->lane_num == 4) {
548			if (LANE_IS_PORT1(attr->lane_id[0]))
549				cif_set_clk_dir(ctx, CIF_CLK_P12P0);
550			else
551				cif_set_clk_dir(ctx, CIF_CLK_P02P1);
552	
553			for (i = 0; (i < csi->lane_num + 1); i++) {
554				if (!i)
555					cif_set_lane_deskew(ctx, attr->lane_id[i],
556							lane_phase[LANE_SKEW_CROSS_CLK]);
557				else if (IS_SAME_PORT(attr->lane_id[0], attr->lane_id[i]))
558					cif_set_lane_deskew(ctx, attr->lane_id[i],
559							lane_phase[LANE_SKEW_CROSS_DATA_NEAR]);
560				else
561					cif_set_lane_deskew(ctx, attr->lane_id[i],
562							lane_phase[LANE_SKEW_CROSS_DATA_FAR]);
563			}
564		} else if (csi->lane_num > 0) {
565			if (ctx->mac_num || !clk_port) {
566				cif_set_clk_dir(ctx, CIF_CLK_FREERUN);
567			} else {
568				if (LANE_IS_PORT1(attr->lane_id[0]))
569					cif_set_clk_dir(ctx, CIF_CLK_P12P0);
570				else
571					cif_set_clk_dir(ctx, CIF_CLK_P02P1);
572			}
573			/* if clk and data are in the same port.*/
574			if (clk_port > 0) {
575				for (i = 0; i < (csi->lane_num + 1); i++) {
576					if (!i)
577						cif_set_lane_deskew(ctx, attr->lane_id[i],
578								lane_phase[LANE_SKEW_CLK]);
579					else
580						cif_set_lane_deskew(ctx, attr->lane_id[i],
581								lane_phase[LANE_SKEW_DATA]);
582				}
583			} else {
584				for (i = 0; i < (csi->lane_num + 1); i++) {
585					if (!i)
586						cif_set_lane_deskew(ctx, attr->lane_id[i],
587								lane_phase[LANE_SKEW_CROSS_CLK]);
588					else if (IS_SAME_PORT(attr->lane_id[0], attr->lane_id[i]))
589						cif_set_lane_deskew(ctx, attr->lane_id[i],
590								lane_phase[LANE_SKEW_CROSS_DATA_NEAR]);
591					else
592						cif_set_lane_deskew(ctx, attr->lane_id[i],
593								lane_phase[LANE_SKEW_CROSS_DATA_FAR]);
594				}
595			}
596		} else
597			return -EINVAL;
598	
599		/* config the dphy seting. */
600		if (attr->dphy.enable)
601			cif_set_hs_settle(ctx, attr->dphy.hs_settle);
602		/* config the wdr mode. */
603		switch (attr->wdr_mode) {
604		case CVI_MIPI_WDR_MODE_NONE:
605			break;
606		case CVI_MIPI_WDR_MODE_DT:
607			csi->hdr_mode = CSI_HDR_MODE_DT;
608			for (i = 0; i < MAX_WDR_FRAME_NUM; i++)
609				csi->data_type[i] = attr->data_type[i];
610			break;
611		case CVI_MIPI_WDR_MODE_MANUAL:
612			param->hdr_manual = combo->wdr_manu.manual_en;
613			param->hdr_shift = combo->wdr_manu.l2s_distance;
614			param->hdr_vsize = combo->wdr_manu.lsef_length;
615			param->hdr_rm_padding = combo->wdr_manu.discard_padding_lines;
616			cif_hdr_manual_config(ctx, param, !!combo->wdr_manu.update);
617			break;
618		case CVI_MIPI_WDR_MODE_VC:
619			csi->hdr_mode = CSI_HDR_MODE_VC;
620			break;
621		case CVI_MIPI_WDR_MODE_DOL:
622			csi->hdr_mode = CSI_HDR_MODE_DOL;
623			break;
624		default:
625			return -EINVAL;
626		}
627		/* config vc mapping */
628		if (info->demux_en) {
629			for (i = 0; i < MIPI_DEMUX_NUM; i++) {
630				csi->vc_mapping[i] = info->vc_mapping[i];
631			}
