1263	void cif_set_lane_id(struct cif_ctx *ctx, enum lane_id_e lane,
1264				uint32_t select, uint32_t pn_swap)
1265	{
1266		uintptr_t wrap_top = ctx->wrap_phys_regs[CIF_WRAP_BLK_ID_TOP];
1267		uintptr_t wrap_4l = ctx->wrap_phys_regs[CIF_WRAP_BLK_ID_4L];
1268		uintptr_t wrap_2l = ctx->wrap_phys_regs[CIF_WRAP_BLK_ID_2L];
1269	
1270		switch (lane) {
1271		case CIF_LANE_CLK:
1272			if (!ctx->mac_num) {
1273				/* PHYA clock select */
1274	
1275				CIF_WR_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1276					      REG_04, MIPIRX_SEL_CLK_CHANNEL,
1277					      CIF_RD_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1278							REG_04, MIPIRX_SEL_CLK_CHANNEL) | 1 << select);
1279				/* PHYD clock select */
1280				CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
1281					      REG_08, CSI_LANE_CK_SEL,
1282					      select);
1283				CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
1284					      REG_08, CSI_LANE_CK_PNSWAP,
1285					      pn_swap);
1286			} else {
1287				/* Enable dual mode */
1288				CIF_WR_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1289					      REG_30, SENSOR_PHY_MODE,
1290					      1);
1291				/* PHYA clock select */
1292				CIF_WR_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1293					      REG_04, MIPIRX_SEL_CLK_CHANNEL,
1294					      CIF_RD_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1295							REG_04, MIPIRX_SEL_CLK_CHANNEL) | 1 << select);
1296				/* PHYD clock select */
1297				CIF_WR_BITS(wrap_2l, REG_SENSOR_PHY_2L_T,
1298					      REG_08, CSI_LANE_CK_SEL,
1299					      select % 3);
1300				CIF_WR_BITS(wrap_2l, REG_SENSOR_PHY_2L_T,
1301					      REG_08, CSI_LANE_CK_PNSWAP,
1302					      pn_swap);
1303			}
1304			break;
1305		case CIF_LANE_0:
1306			if (!ctx->mac_num) {
1307				CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
1308					      REG_04, CSI_LANE_D0_SEL,
1309					      select);
1310				CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
1311					      REG_08, CSI_LANE_D0_PNSWAP,
1312					      pn_swap);
1313			} else {
1314				CIF_WR_BITS(wrap_2l, REG_SENSOR_PHY_2L_T,
1315					      REG_04, CSI_LANE_D0_SEL,
1316					      select % 3);
1317				CIF_WR_BITS(wrap_2l, REG_SENSOR_PHY_2L_T,
1318					      REG_08, CSI_LANE_D0_PNSWAP,
1319					      pn_swap);
1320			}
1321			break;
1322		case CIF_LANE_1:
1323			if (!ctx->mac_num) {
1324				CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
1325					      REG_04, CSI_LANE_D1_SEL,
1326					      select);
1327				CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
1328					      REG_08, CSI_LANE_D1_PNSWAP,
1329					      pn_swap);

1430				      0);
1431			CIF_WR_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1432				      REG_04, MIPIRX_SEL_CLK_P1TOP0,
1433				      0);
1434			break;
1435		default:
1436			break;
1437		}
1438	}
