1448				      REG_10, AUTO_IGNORE,
1449				      0);
1450			CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
1451				      REG_10, AUTO_SYNC,
1452				      0);
1453			CIF_WR_BITS(wrap_4l, REG_SENSOR_PHY_4L_T,
1454				      REG_10, T_HS_SETTLE,
1455				      hs_settle);
1456		} else {
1457			/* disable auto_ignore and auto sync. */
1458			CIF_WR_BITS(wrap_2l, REG_SENSOR_PHY_2L_T,
1459				      REG_10, AUTO_IGNORE,
1460				      0);
1461			CIF_WR_BITS(wrap_2l, REG_SENSOR_PHY_2L_T,
1462				      REG_10, AUTO_SYNC,
1463				      0);
1464			CIF_WR_BITS(wrap_2l, REG_SENSOR_PHY_2L_T,
1465				      REG_10, T_HS_SETTLE,
1466				      hs_settle);
1467	
1468		}
