1471	uint8_t cif_get_lane_data(struct cif_ctx *ctx, enum phy_lane_id_e lane)
1472	{
1473		uintptr_t wrap_top = ctx->wrap_phys_regs[CIF_WRAP_BLK_ID_TOP];
1474		uint8_t value;
1475	
1476		switch (lane) {
1477		case CIF_PHY_LANE_0:
1478			value = CIF_RD_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1479					    REG_70, AD_D0_DATA);
1480			break;
1481		case CIF_PHY_LANE_1:
1482			value = CIF_RD_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1483					    REG_70, AD_D1_DATA);
1484			break;
1485		case CIF_PHY_LANE_2:
1486			value = CIF_RD_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1487					    REG_70, AD_D2_DATA);
1488			break;
1489		case CIF_PHY_LANE_3:
1490			value = CIF_RD_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1491					    REG_70, AD_D3_DATA);
1492			break;
1493		case CIF_PHY_LANE_4:
1494			value = CIF_RD_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1495					    REG_74, AD_D4_DATA);
1496			break;
1497		case CIF_PHY_LANE_5:
1498			value = CIF_RD_BITS(wrap_top, REG_SENSOR_PHY_TOP_T,
1499					    REG_74, AD_D5_DATA);
1500			break;
1501		default:
1502			value = 0;
1503			break;
1504		}
1505	
1506		return value;
1507	}
